-- Expanded Point Lookout Fishing Club starter courses.
-- Update only the original unedited drafts. Published versions and officer edits are preserved.

UPDATE learning_course_versions SET
  description='Get around the member clubhouse and plan your first meet or fishing activity.',
  lessons_json=json_array(
    json('{"title":"Open your member area","body":"Find the member calendar, approved member updates and your own account details. Ask the club about activation and paid membership if an expected area is unavailable.","captureNotes":"Show the public clubhouse and an authorised adult demo account. Reference site: https://plfc-clubhouse.auraofintelligence.workers.dev/"}'),
    json('{"title":"Plan a first outing","body":"Check the event details and ask what to bring and who will meet you. Keep private catch locations, personal details and pictures within the audience you mean to share them with."}'),
    json('{"title":"Check your membership and renewal","body":"Use the current category, member number and status from the club’s own record. If the displayed fee, renewal or pack status differs from what you expect, check with the club before paying twice or creating another account. Keep your receipt and any private activation link for your own use.","captureNotes":"Walk through Clubhouse membership information with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/"}'),
    json('{"title":"Use member discussions and your catch journal","body":"Check who can see a post before adding names, people, images or sensitive catch locations. Correct information through the relevant club contact. If you share a result or competition entry, check the agreed criteria and where it is authorised rather than assuming a journal entry is an official submission.","captureNotes":"Walk through Member clubhouse and catch journal with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/"}'),
    json('{"title":"Prepare, check in and raise concerns","body":"Confirm the conditions, applicable fishing information, official notices and event briefing. Ask who can pause the activity and what gear and conduct are expected. Report a problem to the responsible lead, then follow any agreed handover or equipment return.","captureNotes":"Walk through Club event and fishing guide with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/"}')
  ),
  practical='',
  edit_version=edit_version+1
WHERE course_id='plfc-adult-member' AND revision=1 AND state='draft' AND edit_version=1 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Back up the Secretary across meetings, AGM preparation, notices, officer tasks, newsletters, membership correspondence and handover.',
  lessons_json=json_array(
    json('{"title":"Agree shared responsibilities and covering limits","body":"Walk the current workload with the Secretary on taking office. Identify who owns the meeting record, correspondence, newsletter assembly, member notices and records that need restricted access. Agree whether you are drafting, following up or providing formally authorised cover for a meeting or release. Use your own account and test the actual role access. Record when cover starts, ends and which decisions to escalate. Check the work list with the Secretary each week.\n\nKeep the shared workload, cover limits, approval owner and when the arrangement ends in the authorised record.","captureNotes":"Walk through #committee/handover with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/handover Include the shared workload, cover limits, approval owner and when the arrangement ends using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"The Secretary is away and you are asked to send an unapproved notice. What do you verify?","choices":[{"id":"a","text":"Send it because you are working from the same newsletter desk."},{"id":"b","text":"Check the agreed cover, the record of authority and whether the notice was cleared for that audience."}],"correct_choice_id":"b","explanation":"The operating record needs the shared workload, cover limits, approval owner and when the arrangement ends. This lets the next person verify the work and any remaining decision.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/handover"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record would let an independent reviewer check the result?","choices":[{"id":"a","text":"the shared workload, cover limits, approval owner and when the arrangement ends"},{"id":"b","text":"an informal note saying you are covering everything"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/handover"]}]}'),
    json('{"title":"Prepare meeting material and check the agenda version","body":"Find the next meeting and current agenda. Check the date, location, outstanding actions, submitted reports, motion wording and notice requirements with the Secretary. Keep late items visible as late and ask the Secretary which version will go to members or the committee. Draft the meeting notice and attachments for the correct audience. During authorised cover check attendance, quorum, conflicts, actual decisions and owners against the chair’s notes.\n\nKeep the agenda version, paper references, recipients, notice status and who will issue corrections in the authorised record.","captureNotes":"Walk through #committee/meetings with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/meetings Include the agenda version, paper references, recipients, notice status and who will issue corrections using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"Two staff have prepared different agenda versions and one was already circulated. What is your move?","choices":[{"id":"a","text":"Confirm the current approved version, what was sent and who can issue a correction."},{"id":"b","text":"Circulate the newer version immediately so everyone has the additional papers."}],"correct_choice_id":"a","explanation":"The operating record needs the agenda version, paper references, recipients, notice status and who will issue corrections. This lets the next person verify the work and any remaining decision.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/meetings"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would let the next person verify this work?","choices":[{"id":"a","text":"a folder with both agendas and no distribution record"},{"id":"b","text":"the agenda version, paper references, recipients, notice status and who will issue corrections"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/meetings"]}]}'),
    json('{"title":"Record decisions and close follow-up actions","body":"Compare approved decisions with the officer lists. Put each action on the right office’s list with a due date and source. Print individual lists on club letterhead when used. Check returned sheets with the officer where the marks or dates are unclear, then record completion or reopen the correct item. Do not publish working notes or transcript suggestions as minutes. Keep owner and completion evidence with the original decision.\n\nKeep the motion reference, assigned officer, due date and evidence for the part completed in the authorised record.","captureNotes":"Walk through #committee/todo with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/todo Include the motion reference, assigned officer, due date and evidence for the part completed using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A paper sheet marks a job done but the payment approval it depends on is still open. What do you record?","choices":[{"id":"a","text":"Mark the whole action complete and leave the decision source unlinked."},{"id":"b","text":"Confirm the scope of what was done and leave the approval dependency open with a named follow-up."}],"correct_choice_id":"b","explanation":"The operating record needs the motion reference, assigned officer, due date and evidence for the part completed. This lets the next person verify the work and any remaining decision.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/todo"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record gives the incoming person enough evidence to follow up?","choices":[{"id":"a","text":"the motion reference, assigned officer, due date and evidence for the part completed"},{"id":"b","text":"a tick against the job without the unresolved dependency"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/todo"]}]}'),
    json('{"title":"Support AGM papers, nominations and outcomes","body":"Work through AGM jobs with the Secretary. Find the last signed AGM record, current rules, notice basis, confirmed report versions and the nominations the Secretary is authorised to handle. Log responsibility and due dates. Flag missing papers or late notices promptly so the responsible officers can check the rules. After the meeting help reconcile declared outcomes, paperwork and statutory follow-up owners before archiving the correct version.\n\nKeep the AGM checklist showing the report version, nominations status and authorised next step in the authorised record.","captureNotes":"Walk through #committee/agm-jobs with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/agm-jobs Include the AGM checklist showing the report version, nominations status and authorised next step using invented details. Confirm any meeting or filing procedures against the current adopted or proposed rules as applicable and current Queensland Fair Trading guidance. For child-related duties, check the designated safeguarding lead and current Queensland guidance.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"The report is ready but the nominations record is incomplete before circulation. What do you do?","choices":[{"id":"a","text":"Flag the missing nominations evidence and ask the Secretary which items can be circulated and when."},{"id":"b","text":"Fill the gaps using names from the previous AGM so the papers can go out."}],"correct_choice_id":"a","explanation":"The operating record needs the AGM checklist showing the report version, nominations status and authorised next step. This lets the next person verify the work and any remaining decision.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/agm-jobs"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which evidence belongs in the work record for this step?","choices":[{"id":"a","text":"an AGM pack with blank nomination fields and no owner"},{"id":"b","text":"the AGM checklist showing the report version, nominations status and authorised next step"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/agm-jobs"]}]}'),
    json('{"title":"Assemble newsletters and member updates","body":"Open the month’s shared edition and agree who is editing and who will release it. Check contribution history for missing President, Vice President, Treasurer and other items. Draft your own club or volunteer update with confirmed dates and intended audience. Use the member preview and check images, credits, status and linked notices. Record clearance or the revision needed. If working on a public channel, use the social planner and the right publication approval. File the published version or link.\n\nKeep the current issue version, contribution gaps, audience approval and publication owner in the authorised record.","captureNotes":"Walk through #committee/news with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/news Include the current issue version, contribution gaps, audience approval and publication owner using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"Two officers want to release slightly different drafts on the same day. What should you do?","choices":[{"id":"a","text":"Send the member draft by one channel and the second draft by another so both contributions appear."},{"id":"b","text":"Agree the current draft, resolve the difference in review and identify one authorised release owner."}],"correct_choice_id":"b","explanation":"The operating record needs the current issue version, contribution gaps, audience approval and publication owner. This lets the next person verify the work and any remaining decision.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/news"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would make this part of the handover usable?","choices":[{"id":"a","text":"the current issue version, contribution gaps, audience approval and publication owner"},{"id":"b","text":"two preview links with instructions to pick whichever opens"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/news"]}]}'),
    json('{"title":"Review birthdays and member communications privately","body":"Open the shared monthly birthday review with the Secretary. Check member opt-in, approved offer terms and who can handle any private greeting or code. Track work in a single record so the two offices do not duplicate it. In the member notices and delivery workflow, check intended audience, authority, content and actual delivery status. A queued notice or a suggested date is a working record. Keep member details outside public drafts and screenshots.\n\nKeep the shared review status, opt-in check, offer approval and handling owner in the authorised record.","captureNotes":"Walk through #committee/news with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/news Include the shared review status, opt-in check, offer approval and handling owner using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A birthday appears in the register but the member did not opt in to a greeting. What do you record?","choices":[{"id":"a","text":"Leave it outside the greeting work and check any consent question through the authorised member process."},{"id":"b","text":"Schedule a private greeting because private delivery does not require a preference check."}],"correct_choice_id":"a","explanation":"The operating record needs the shared review status, opt-in check, offer approval and handling owner. This lets the next person verify the work and any remaining decision.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/news"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record would let an independent reviewer check the result?","choices":[{"id":"a","text":"a copied birthday list with no permission or sending status"},{"id":"b","text":"the shared review status, opt-in check, offer approval and handling owner"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/news"]}]}'),
    json('{"title":"Support applications, returns and member packs","body":"Check the current application or historic registration with the Secretary. Look for an existing application or returning offer before preparing work. Keep application review and member number, payment confirmation, waiver approval and private invitation as separate steps. Pass payment or waiver questions to the Treasurer with its reference. Route youth and online access decisions to the authorised guardian and club review process. Coordinate the pack handover with the named lead and record what has actually been issued.\n\nKeep the membership reference, clearance status, pack owner and outstanding Treasurer or Secretary decision in the authorised record.","captureNotes":"Walk through #committee/returning with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/returning Include the membership reference, clearance status, pack owner and outstanding Treasurer or Secretary decision using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A known member is waiting for an invitation and the waiver has not been decided. What should you do?","choices":[{"id":"a","text":"Send an invitation now and let the Treasurer reconcile the waiver after activation."},{"id":"b","text":"Keep the offer pending, refer the waiver to the Treasurer and record who contacts the member next."}],"correct_choice_id":"b","explanation":"The operating record needs the membership reference, clearance status, pack owner and outstanding Treasurer or Secretary decision. This lets the next person verify the work and any remaining decision.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/returning"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would let the next person verify this work?","choices":[{"id":"a","text":"the membership reference, clearance status, pack owner and outstanding Treasurer or Secretary decision"},{"id":"b","text":"the applicant’s contact details and a ready-to-send link without payment or waiver status"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/returning"]}]}'),
    json('{"title":"Hand over correspondence, records and deadlines","body":"Bring the latest meeting and newsletter versions, notices, calendar, correspondence needing a reply, membership follow-ups and open AGM jobs to the handover. File references in the authorised location. Ask the Secretary to confirm restricted items and whether anything temporarily needs cover. Escalate a complaint or missing record through the agreed officer rather than sharing the content in a general list. Agree a check-in and have the incoming officer show they can find the work using their own authorised access.\n\nKeep an outstanding work list with current sources, private routes, cover and next review in the authorised record.","captureNotes":"Walk through #committee/handover with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/handover Include an outstanding work list with current sources, private routes, cover and next review using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"An unresolved complaint is linked to a task due after the transition. What do you hand over?","choices":[{"id":"a","text":"The restricted reference, authorised contact, next action and deadline, with access verified."},{"id":"b","text":"A copy in the shared newsletter folder so the next officer can find it easily."}],"correct_choice_id":"a","explanation":"The operating record needs an outstanding work list with current sources, private routes, cover and next review. This lets the next person verify the work and any remaining decision.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/handover"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record gives the incoming person enough evidence to follow up?","choices":[{"id":"a","text":"a single public copy of the inbox and task list"},{"id":"b","text":"an outstanding work list with current sources, private routes, cover and next review"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/handover"]}]}')
  ),
  practical='Using fictional records, prepare a shared office work pack. Show who owns the next agenda, three meeting actions, a returned paper list, an upcoming AGM job, a newsletter item that needs revision and an opt-in birthday review. Include a pending member or return request and one restricted item to refer on. End with the version of each record and a first-week check-in. Pass when the Secretary could pick up every open item, verify its status and see which release or approval remains with an authorised officer.',
  edit_version=edit_version+1
WHERE course_id='plfc-assistant-secretary' AND revision=1 AND state='draft' AND edit_version=1 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Help a cadet and their guardian plan a supported first club session.',
  lessons_json=json_array(
    json('{"title":"Plan the first visit together","body":"Choose a suitable club activity with the guardian. Ask who will lead, how the young person checks in and which equipment they should bring. The guardian deals with the application and current permissions.","captureNotes":"Use a fictional family and the public membership information. Keep details of real young people private. Reference site: https://plfc-clubhouse.auraofintelligence.workers.dev/"}'),
    json('{"title":"Ask before sharing","body":"Check with the designated lead about supervision and photo arrangements. Ask the guardian separately about online participation and check the club’s review before using those features."}'),
    json('{"title":"Application, permission and first check-in","body":"The guardian checks the current category and application process, then confirms who can collect and supervise the cadet and how to report a change. Use a private route for health or support information and confirm the lead has received the information they need.","captureNotes":"Walk through Public join information and club event with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/"}'),
    json('{"title":"Prepare appropriate gear and support","body":"Ask the activity lead what the cadet should bring, what can be supplied, how an unfamiliar task will be demonstrated and what to do if conditions change. Confirm where the young person can take a break and who can help.","captureNotes":"Walk through Club fishing guide and event information with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/"}'),
    json('{"title":"Photo choices and speaking up","body":"Ask how attendance, photography and online access are handled separately. The guardian and cadet can ask about where a record is shared and use the agreed private contact for a concern. Follow up after the session if access, pickup or a safety arrangement was unclear.","captureNotes":"Walk through Clubhouse terms and designated safeguarding contact with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/"}')
  ),
  practical='',
  edit_version=edit_version+1
WHERE course_id='plfc-cadet-member' AND revision=1 AND state='draft' AND edit_version=1 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Check the conditions for a visit or one-off activity before making plans.',
  lessons_json=json_array(
    json('{"title":"Confirm what the category covers","body":"Find the club’s current public join information. Ask which activity your casual membership covers and whether there are fees, capacity limits or advance arrangements.","captureNotes":"Capture the public join options with no application entered. Reference site: https://plfc-clubhouse.auraofintelligence.workers.dev/"}'),
    json('{"title":"Check in for the day","body":"Bring the public event details and confirm your meeting point and contact. Ask how to find updates if the plans change and report anything the next crew should know."}'),
    json('{"title":"Check terms for a specific session","body":"Ask whether your category covers the specific event, if space must be reserved, and what current fee or refund arrangements apply. Find out what confirmation looks like and keep the agreed contact or reference for changes.","captureNotes":"Walk through Public membership and events pages with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/"}'),
    json('{"title":"Prepare the first visit","body":"Confirm start, meeting point, required equipment, experience level and any supervision or accessibility needs. Check the current conditions and event message from the responsible lead before travelling. Use a private contact if personal support information is needed.","captureNotes":"Walk through Event listing and conditions briefing with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/"}'),
    json('{"title":"Changes, check-out and next visit","body":"If your attendance changes, ask the organiser what substitutions or cancellation steps apply. At the end return borrowed gear, report a problem and check whether you can receive future updates or seek another category separately.","captureNotes":"Walk through Event contact and public calendar with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/"}')
  ),
  practical='',
  edit_version=edit_version+1
WHERE course_id='plfc-casual-member' AND revision=1 AND state='draft' AND edit_version=1 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Find an appropriate junior activity and understand the clubhouse sharing choices.',
  lessons_json=json_array(
    json('{"title":"Choose an activity with your guardian","body":"Ask about the activity, skill level, supervision and equipment before coming along. Confirm the meeting point and what to do if you or the guardian need help.","captureNotes":"Show the public youth application choice and fictional event details. Reference site: https://plfc-clubhouse.auraofintelligence.workers.dev/"}'),
    json('{"title":"Use the online area with approved access","body":"Speak up if you are unsure about an online message, photo or activity. A guardian and the club review online participation separately. Ask the lead how to report a concern."}'),
    json('{"title":"Choose the right activity level","body":"Together check age, skill requirements, safe access and what equipment or support is available. Confirm meeting point, pickup and any expected cost directly with the lead. If a listing changes, ask the guardian and lead to confirm the new arrangement.","captureNotes":"Walk through Public calendar and fishing guide with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/"}'),
    json('{"title":"Use the clubhouse responsibly","body":"Check who can see a catch photo, post or location and what online access has been approved. Keep login and other people’s details private. If you see an uncomfortable post or message, tell your guardian or designated club contact through the appropriate private route.","captureNotes":"Walk through Member clubhouse and clubhouse terms with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/"}'),
    json('{"title":"Activity rules and follow-up","body":"Ask who explains the session or competition rules, demonstrates equipment and confirms how any result can be shared. Let the lead know when you need help or want to stop. At the end return equipment and discuss feedback and future participation with your guardian.","captureNotes":"Walk through Club event and results information with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/ Confirm any meeting or filing procedures against the current adopted or proposed rules as applicable and current Queensland Fair Trading guidance. For child-related duties, check the designated safeguarding lead and current Queensland guidance."}')
  ),
  practical='',
  edit_version=edit_version+1
WHERE course_id='plfc-junior-member' AND revision=1 AND state='draft' AND edit_version=1 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Find the current clubhouse, check your existing record and choose how to contribute.',
  lessons_json=json_array(
    json('{"title":"Update your connection with the club","body":"Use the club contact to confirm the current lifetime membership record and sign-in. Ask how to update your preferences and where to find member notices.","captureNotes":"Show the demo sign-in and a fictional member contact update. Reference site: https://plfc-clubhouse.auraofintelligence.workers.dev/"}'),
    json('{"title":"Share knowledge by agreement","body":"Offer a story, guide or mentoring time to the club. Check before sharing another member’s names, records, old photos or private catch locations."}'),
    json('{"title":"Verify the historic record and update access","body":"Take the evidence you already have to the authorised club contact and check how the historic record relates to the current one. Ask about status, personal details and account access. Avoid duplicate applications or publicly posting a historic member number.","captureNotes":"Walk through Clubhouse member contact with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/"}'),
    json('{"title":"Decide what to share from the archive","body":"Before offering a photo, member list, story or old report, identify its source, any sensitive details and who can approve use. Agree the audience and credit. Let the club keep the original record and track any edits or permitted public copy separately.","captureNotes":"Walk through Club records and newsletter contact with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/"}'),
    json('{"title":"Agree mentoring or support","body":"Discuss what you can comfortably offer, what the event lead needs and who supervises. Confirm equipment custody, timing and how to share feedback. Hand over unfinished work or historical context to the appropriate officer using the club’s preferred record.","captureNotes":"Walk through Club events and officer contact with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/"}')
  ),
  practical='',
  edit_version=edit_version+1
WHERE course_id='plfc-lifetime-member' AND revision=1 AND state='draft' AND edit_version=1 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Run a full cross-office PLFC changeover with a checked governance, membership, finance, events, communication and access handover.',
  lessons_json=json_array(
    json('{"title":"Confirm appointments, rules and who owns the work","body":"Check the appointment record, actual current rules and decisions affecting each office. Find the five named officer guides. Use the shared handover to identify backup cover, who may approve or publish and which items come back to the committee or members. The V1.2 clubhouse archive should be checked against the club’s adopted records before using notice, quorum or election procedures. List unresolved appointments, approvals and deadlines early.\n\nKeep the verified appointment and rules references, handover scope and owners in the authorised record.","captureNotes":"Walk through #committee/handover with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/handover Include the verified appointment and rules references, handover scope and owners using invented details. Confirm any meeting or filing procedures against the current adopted or proposed rules as applicable and current Queensland Fair Trading guidance. For child-related duties, check the designated safeguarding lead and current Queensland guidance.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"The website displays an office but there is no signed appointment record. What do you do?","choices":[{"id":"a","text":"Check the actual decision and approved rules with the Secretary before recording authority."},{"id":"b","text":"Assign duties based on what appears in the navigation."}],"correct_choice_id":"a","explanation":"The operating record needs the verified appointment and rules references, handover scope and owners. This lets the next person verify the work and any remaining decision.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/handover"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record would let an independent reviewer check the result?","choices":[{"id":"a","text":"an officer list copied from the site"},{"id":"b","text":"the verified appointment and rules references, handover scope and owners"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/handover"]}]}'),
    json('{"title":"Take over meetings, action lists and AGM jobs","body":"Review the latest approved minutes, next committee and general meetings, AGM notices and nominations, Treasurer reports, filing dates and any deferred decision. Check who will chair, minute and send member notices. Carry named actions, dependencies and evidence into Officer to-do lists. Record any issue about quorum, an adjournment or a missing decision for the Chair and Secretary to resolve against current rules.\n\nKeep the current decision, meeting, AGM and filing trail with named owners in the authorised record.","captureNotes":"Walk through #committee/agm-jobs with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/agm-jobs Include the current decision, meeting, AGM and filing trail with named owners using invented details. Confirm any meeting or filing procedures against the current adopted or proposed rules as applicable and current Queensland Fair Trading guidance. For child-related duties, check the designated safeguarding lead and current Queensland guidance.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"The filing checklist says done but the lodgement receipt is missing. Which item stays open?","choices":[{"id":"a","text":"A general record that the AGM was held."},{"id":"b","text":"The specific receipt check, responsible officer and due date."}],"correct_choice_id":"b","explanation":"The operating record needs the current decision, meeting, AGM and filing trail with named owners. This lets the next person verify the work and any remaining decision.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/agm-jobs"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would let the next person verify this work?","choices":[{"id":"a","text":"the current decision, meeting, AGM and filing trail with named owners"},{"id":"b","text":"the meeting dates and a vague reminder to look for records"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/agm-jobs"]}]}'),
    json('{"title":"Pass over membership duties and restricted matters","body":"Walk through member register references, latest applications and renewals, receipts or waivers, private invitations, member packs and reminders. Confirm who may access each record and who deals with youth permissions or concerns. Use the appropriate private contact route for complaints or sensitive evidence. Give the incoming team the stage and required action, with a reference to the source and no unnecessary personal details.\n\nKeep register references, owners, approval gaps and restricted follow-up for pending work in the authorised record.","captureNotes":"Walk through #committee/applications with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/applications Include register references, owners, approval gaps and restricted follow-up for pending work using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A returning offer is drafted but the waiver has not been confirmed. How do you transfer it?","choices":[{"id":"a","text":"Flag the pending Treasurer decision and give the Secretary the authorised follow-up reference."},{"id":"b","text":"Treat the welcome-back draft as approval and send the invite."}],"correct_choice_id":"a","explanation":"The operating record needs register references, owners, approval gaps and restricted follow-up for pending work. This lets the next person verify the work and any remaining decision.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/applications"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record gives the incoming person enough evidence to follow up?","choices":[{"id":"a","text":"a spreadsheet of contact details and assumed approvals"},{"id":"b","text":"register references, owners, approval gaps and restricted follow-up for pending work"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/applications"]}]}'),
    json('{"title":"Check finance, stock, equipment and commitments","body":"Reconcile the finance handover with the outgoing and incoming Treasurer. Locate approved budgets, outstanding invoices, bank checks, stock and unit costs, assets in other people’s custody, grants and restricted spending. Record which items lack receipts, an authoriser or a physical count. Confirm shop, event and membership pricing decisions and who verifies incoming access. Carry operational and filing deadlines into the record.\n\nKeep the reconciled position, asset custody, cost evidence, exceptions and deadlines in the authorised record.","captureNotes":"Walk through #stock/reports with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/#stock/reports Include the reconciled position, asset custody, cost evidence, exceptions and deadlines using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"An asset is loaned and the invoice is still outstanding. What does the handover need?","choices":[{"id":"a","text":"Its catalogue price and a note the club has it somewhere."},{"id":"b","text":"Its custody, receipt or cost gap, owner and when the next review occurs."}],"correct_choice_id":"b","explanation":"The operating record needs the reconciled position, asset custody, cost evidence, exceptions and deadlines. This lets the next person verify the work and any remaining decision.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#stock/reports"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which evidence belongs in the work record for this step?","choices":[{"id":"a","text":"the reconciled position, asset custody, cost evidence, exceptions and deadlines"},{"id":"b","text":"an export of totals with no source or equipment record"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#stock/reports"]}]}'),
    json('{"title":"Orient events, safeguarding and partner work","body":"Open the upcoming meets and fundraising plans. Check venue, times, volunteer leads, briefing, equipment, permissions and the person who can pause or call a change. Review the restricted safeguarding contact and appropriate incident follow-up. For any Ready SETCO or interclub task, distinguish enquiry from approved scope and written acceptance, retained responsibilities, authorised contacts and a review date. Leave missing decisions visible in the handover.\n\nKeep the latest run sheet, briefing, authority and actual partner acceptance or gap in the authorised record.","captureNotes":"Walk through #committee/events with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/events Include the latest run sheet, briefing, authority and actual partner acceptance or gap using invented details. Confirm any meeting or filing procedures against the current adopted or proposed rules as applicable and current Queensland Fair Trading guidance. For child-related duties, check the designated safeguarding lead and current Queensland guidance.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A partner wants to deliver an event and the roster is ready. What still matters?","choices":[{"id":"a","text":"Confirm venue, safety decisions and the exact accepted scope and duties retained by the club."},{"id":"b","text":"Publish the programme since the roster establishes all delivery authority."}],"correct_choice_id":"a","explanation":"The operating record needs the latest run sheet, briefing, authority and actual partner acceptance or gap. This lets the next person verify the work and any remaining decision.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/events"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would make this part of the handover usable?","choices":[{"id":"a","text":"an event flyer with the listed partners and no evidence"},{"id":"b","text":"the latest run sheet, briefing, authority and actual partner acceptance or gap"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/events"]}]}'),
    json('{"title":"Coordinate newsletter, notices and public posts","body":"Identify the current issue, outstanding contributions, review roles, birthday opt-in check and member-release actor. Check the event calendar, current decision source and audience before publishing public scheduled posts. Record the actual link or sends, and who will fix a mistake or carry over an update. Keep private material in its correct audience and preserve the approved versions.\n\nKeep the approved versions, channels, actual releases and pending corrections in the authorised record.","captureNotes":"Walk through #committee/news with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/news Include the approved versions, channels, actual releases and pending corrections using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"Two updates about one meet give different times. What should the incoming officers use?","choices":[{"id":"a","text":"Mark the newsletter latest and leave the public post to expire."},{"id":"b","text":"Confirm the correct current source and assign someone to fix and verify every affected channel."}],"correct_choice_id":"b","explanation":"The operating record needs the approved versions, channels, actual releases and pending corrections. This lets the next person verify the work and any remaining decision.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/news"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record would let an independent reviewer check the result?","choices":[{"id":"a","text":"the approved versions, channels, actual releases and pending corrections"},{"id":"b","text":"a screenshot of one draft with no approval or channel details"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/news"]}]}'),
    json('{"title":"Check account, records and property custody","body":"Give each incoming officer their own account through the authorised Webmaster process. Verify their actual access and remove or review outgoing privileges as directed. Log the custody of equipment, documents and other assets, including recovery contacts and backup location for authorised people. Demonstrate where to get support. Use approved fictional or sanitised data for training and avoid passing old credentials or unnecessary private copies.\n\nKeep the custody checklist, scope checks, unresolved access and custodian references in the authorised record.","captureNotes":"Walk through #committee/handover with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/handover Include the custody checklist, scope checks, unresolved access and custodian references using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"How should the new committee confirm unpublished committee records are protected?","choices":[{"id":"a","text":"Test permitted and denied access in separate sessions and record the scope review."},{"id":"b","text":"Check that the Webmaster can see the private pages when using a preview."}],"correct_choice_id":"a","explanation":"The operating record needs the custody checklist, scope checks, unresolved access and custodian references. This lets the next person verify the work and any remaining decision.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/handover"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would let the next person verify this work?","choices":[{"id":"a","text":"a shared set of passwords and one successful admin sign-in"},{"id":"b","text":"the custody checklist, scope checks, unresolved access and custodian references"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/handover"]}]}'),
    json('{"title":"Confirm first-week priorities and close the handover","body":"Schedule a first-week review of the most time-sensitive governance, membership, finance and event tasks. Confirm every gap has an owner, evidence to obtain and a deadline. Walk the incoming team through one decision, a follow-up and a restricted case handoff. Revisit outstanding dates and ask the responsible officers to confirm what was resolved. File the agreed handover and date for checking remaining matters.\n\nKeep a dated completion and exceptions record with evidence and follow-up owners in the authorised record.","captureNotes":"Walk through #committee/handover with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/handover Include a dated completion and exceptions record with evidence and follow-up owners using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"The successor can sign in but has not found the approved event decision. Can the transfer be closed?","choices":[{"id":"a","text":"Close the transfer and ask them to reconstruct it later from public updates."},{"id":"b","text":"Keep that check open with a named person, source to find and review date."}],"correct_choice_id":"b","explanation":"The operating record needs a dated completion and exceptions record with evidence and follow-up owners. This lets the next person verify the work and any remaining decision.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/handover"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record gives the incoming person enough evidence to follow up?","choices":[{"id":"a","text":"a dated completion and exceptions record with evidence and follow-up owners"},{"id":"b","text":"a signed attendance sheet with no review of open work"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/handover"]}]}')
  ),
  practical='Use fictional PLFC records to prepare a shared handover and office-by-office schedule. Trace one approval from a meeting through the action and public update, and one membership or fee exception through the right owner. Include an AGM filing, finance or equipment evidence, a restricted safeguarding route, one proposed partner task and incoming and outgoing access checks. Pass when a successor can locate each current record, identify its authority and retained duties, and demonstrate the first-week review.',
  edit_version=edit_version+1
WHERE course_id='plfc-officer-handover' AND revision=1 AND state='draft' AND edit_version=2 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Chair PLFC’s committee and member meetings, follow through on decisions, and oversee the club’s events, finances, member safeguards and communications.',
  lessons_json=json_array(
    json('{"title":"Take up the chair and agree delegations","body":"Start with the club’s confirmed appointment record and current adopted rules. The clubhouse V1.2 archive has an unverified adoption date. Ask the Secretary which rules are in force and where the evidence is kept. Agree which decisions sit with members, the committee or a delegated officer, and what the Vice President can cover. Check any pending grant, venue or supplier promise against its authority before representing it as agreed. Record the limits and review date with the handover.\n\nKeep the appointment reference, adopted-rules reference and current authority limits in the authorised record.","captureNotes":"Walk through #committee/handover with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/handover Include the appointment reference, adopted-rules reference and current authority limits using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A sponsor asks you to confirm an offer that appears in a draft budget. What do you check first?","choices":[{"id":"a","text":"Sign within the estimate because the President represents the club."},{"id":"b","text":"Check the current rules, recorded decision, limits and who can accept the offer."}],"correct_choice_id":"b","explanation":"The operating record needs the appointment reference, adopted-rules reference and current authority limits. This lets the next person verify the work and any remaining decision.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/handover"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would let the next person verify this work?","choices":[{"id":"a","text":"the appointment reference, adopted-rules reference and current authority limits"},{"id":"b","text":"the website role badge and the latest budget"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/handover"]}]}'),
    json('{"title":"Build a decision-ready agenda","body":"Before each committee or general meeting, work with the Secretary to confirm the correct meeting type, notice, papers and eligible participants. Separate reports for noting from resolutions requiring a decision. Check deferred items, quorum requirements and which decisions must go to members. Ask the Treasurer for the evidence behind any spending proposal and assign a presenter to each item. Send late papers through the agreed notice and deferral process.\n\nKeep an agenda with each decision, evidence reference, presenter and notice status in the authorised record.","captureNotes":"Walk through #committee/meetings with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/meetings Include an agenda with each decision, evidence reference, presenter and notice status using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A new spending proposal comes in just before a general meeting. How should you prepare?","choices":[{"id":"a","text":"Check whether it can be dealt with under the existing notice and rules, and defer if it needs a separate process."},{"id":"b","text":"Add it to other business with a plan to vote if enough members attend."}],"correct_choice_id":"a","explanation":"The operating record needs an agenda with each decision, evidence reference, presenter and notice status. This lets the next person verify the work and any remaining decision.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/meetings"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record gives the incoming person enough evidence to follow up?","choices":[{"id":"a","text":"a list of subjects and a suggested meeting length"},{"id":"b","text":"an agenda with each decision, evidence reference, presenter and notice status"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/meetings"]}]}'),
    json('{"title":"Chair, declare interests and confirm outcomes","body":"Open with attendance and quorum and ask about interests before the relevant items. When an interest is disclosed, check the applicable process, record it and have the Secretary confirm what happens to participation and quorum. Keep discussion to the motion. Ask for the final wording and voting outcome to be read back. If authority or quorum fails, record the issue and use the rules for deferral or adjournment. Agree the action owner and due date before moving on.\n\nKeep the final motion, outcome, declaration handling, quorum and action owner in the authorised record.","captureNotes":"Walk through #committee/meetings with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/meetings Include the final motion, outcome, declaration handling, quorum and action owner using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A declaration leaves the meeting short of quorum for a motion. What should the chair do?","choices":[{"id":"a","text":"Use a show of hands from those remaining and ask the next meeting to ratify it."},{"id":"b","text":"Pause that decision, record the quorum issue and follow the rules for the next step."}],"correct_choice_id":"b","explanation":"The operating record needs the final motion, outcome, declaration handling, quorum and action owner. This lets the next person verify the work and any remaining decision.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/meetings"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which evidence belongs in the work record for this step?","choices":[{"id":"a","text":"the final motion, outcome, declaration handling, quorum and action owner"},{"id":"b","text":"the initial motion and a note the room generally agreed"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/meetings"]}]}'),
    json('{"title":"Run the AGM and support the office changeover","body":"Review the AGM checklist with the Secretary and Treasurer. Confirm the meeting basis, notice, membership eligibility, nominations, election process, minutes and required reports under the current rules. Check that the Treasurer’s approved year-end material is ready for members. Handle adjournment, tied votes or a vacancy using the governing rules and record the outcome. After the AGM, confirm the incoming team’s authority, filings owner and dates, club property and review of access.\n\nKeep the AGM basis, notice and nomination evidence, declared results and follow-up owners in the authorised record.","captureNotes":"Walk through #committee/agm-jobs with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/agm-jobs Include the AGM basis, notice and nomination evidence, declared results and follow-up owners using invented details. Confirm any meeting or filing procedures against the current adopted or proposed rules as applicable and current Queensland Fair Trading guidance. For child-related duties, check the designated safeguarding lead and current Queensland guidance.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"An earlier AGM lacked quorum and its status is unclear. What do you do?","choices":[{"id":"a","text":"Check the original record and confirmed rules with the Secretary before treating the next meeting as a continuation."},{"id":"b","text":"Re-use the old notice because the same reports are on the agenda."}],"correct_choice_id":"a","explanation":"The operating record needs the AGM basis, notice and nomination evidence, declared results and follow-up owners. This lets the next person verify the work and any remaining decision.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/agm-jobs"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would make this part of the handover usable?","choices":[{"id":"a","text":"a new meeting date with the previous agenda reused"},{"id":"b","text":"the AGM basis, notice and nomination evidence, declared results and follow-up owners"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/agm-jobs"]}]}'),
    json('{"title":"Oversee finance, grants and commitments","body":"Ask the Treasurer for reconciled results, outstanding items, approved budget and commitments due. Check who may approve or ratify a payment and that the decision is recorded. Review grant applicant authority, conditions, restricted spending, returns and conflicts before endorsing a proposal. Take sponsor or supplier commitments through the proper decision process. Use the committee report for oversight and leave individual ledger entries to the authorised finance team.\n\nKeep a report showing variances, approvals, funding deadlines and named follow-ups in the authorised record.","captureNotes":"Walk through #committee/grants with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/grants Include a report showing variances, approvals, funding deadlines and named follow-ups using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A grant report shows the project is on budget but an unapproved cost change is pending. What should you ask?","choices":[{"id":"a","text":"Accept the change because the total budget still balances."},{"id":"b","text":"Ask for the funding conditions, variance evidence and authorised decision before treating the change as cleared."}],"correct_choice_id":"b","explanation":"The operating record needs a report showing variances, approvals, funding deadlines and named follow-ups. This lets the next person verify the work and any remaining decision.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/grants"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record would let an independent reviewer check the result?","choices":[{"id":"a","text":"a report showing variances, approvals, funding deadlines and named follow-ups"},{"id":"b","text":"one net total and an informal note that invoices will be filed"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/grants"]}]}'),
    json('{"title":"Oversee meets, safeguarding and delegated events","body":"Use Events and fundraising to check the lead, venue and time, volunteer cover, gear, briefing, permission, welfare and who can pause the activity. Confirm the safeguarding lead and restricted escalation route for a concern. Where a partner is proposed, check the approved decision and exact task, duties retained by PLFC, club lead, review date and written acceptance in the authority register. Follow up any incident through the responsible lead and record the action without circulating private details.\n\nKeep the event lead, safety decision, private escalation route and exact accepted delegation in the authorised record.","captureNotes":"Walk through #committee/events with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/events Include the event lead, safety decision, private escalation route and exact accepted delegation using invented details. Confirm any meeting or filing procedures against the current adopted or proposed rules as applicable and current Queensland Fair Trading guidance. For child-related duties, check the designated safeguarding lead and current Queensland guidance.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A partner has offered to roster volunteers and the event lead thinks this transfers on-site supervision. What should you check?","choices":[{"id":"a","text":"Check the recorded scope and retained PLFC responsibilities and keep the handover pending until acceptance is recorded."},{"id":"b","text":"Accept responsibility has transferred because the partner agreed to find volunteers."}],"correct_choice_id":"a","explanation":"The operating record needs the event lead, safety decision, private escalation route and exact accepted delegation. This lets the next person verify the work and any remaining decision.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/events"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would let the next person verify this work?","choices":[{"id":"a","text":"the partner’s offer and a roster with no supervision owner"},{"id":"b","text":"the event lead, safety decision, private escalation route and exact accepted delegation"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/events"]}]}'),
    json('{"title":"Release the President’s message and follow decisions","body":"Draft the President’s contribution in the newsletter desk against approved minutes and confirmed dates. Check the edition with the Secretaries, including the intended audience, permissions, draft status and what is waiting for change. Review or return the edition as assigned. Use the social planner for proposed public messages and verify outlet, approved wording and actual link afterwards. Between meetings, use officer lists to check owners, delays and decisions that need to come back.\n\nKeep the cleared wording, release owner, channel and the open action for confirmation in the authorised record.","captureNotes":"Walk through #committee/news with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/news Include the cleared wording, release owner, channel and the open action for confirmation using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"The newsletter says a neighbouring club will attend when it has only expressed interest. What do you do?","choices":[{"id":"a","text":"Release the edition with a private note that the other club may still decline."},{"id":"b","text":"Return that wording for correction and ask the lead to confirm any later agreement."}],"correct_choice_id":"b","explanation":"The operating record needs the cleared wording, release owner, channel and the open action for confirmation. This lets the next person verify the work and any remaining decision.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/news"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record gives the incoming person enough evidence to follow up?","choices":[{"id":"a","text":"the cleared wording, release owner, channel and the open action for confirmation"},{"id":"b","text":"a draft headline with an expected publication date"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/news"]}]}'),
    json('{"title":"Hand over the whole office","body":"Do a dated walkthrough with the incoming President. Open the next agenda, last decisions, outstanding concerns, finance overview, calendar, public statements and agreement review dates. Name an owner for each open obligation and show which records are private. Have the Webmaster verify their individual access and review the outgoing access. Set a first-week meeting to check missed decisions, role coverage and unresolved issues. File the handover reference in the club’s authorised records.\n\nKeep a dated handover with records, authority gaps, actions, access checks and the first-week review in the authorised record.","captureNotes":"Walk through #committee/handover with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/handover Include a dated handover with records, authority gaps, actions, access checks and the first-week review using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"The incoming President has access but cannot find the authority for an upcoming event. What closes the handover gap?","choices":[{"id":"a","text":"Find or escalate the missing decision, agree who verifies it and record the date for checking again."},{"id":"b","text":"Treat successful sign-in as verification that all handover work is complete."}],"correct_choice_id":"a","explanation":"The operating record needs a dated handover with records, authority gaps, actions, access checks and the first-week review. This lets the next person verify the work and any remaining decision.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/handover"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which evidence belongs in the work record for this step?","choices":[{"id":"a","text":"a sign-in confirmation and a general list of committee contacts"},{"id":"b","text":"a dated handover with records, authority gaps, actions, access checks and the first-week review"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/handover"]}]}')
  ),
  practical='Use a fictional committee meeting followed by an AGM and an interclub meet. Submit a chair''s pack with an agenda, which rules and notice you checked, how you would handle a disclosed interest and lost quorum, a motion and action log, and the AGM or event decisions still open. Include a finance and safeguarding escalation, a reviewed President’s message, and a first-week handover. Pass when the pack shows who can decide, what evidence supports each commitment, and how the Secretary and next chair can verify and follow through.',
  edit_version=edit_version+1
WHERE course_id='plfc-president' AND revision=1 AND state='draft' AND edit_version=1 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Run PLFC’s meeting, AGM, membership and correspondence records, coordinate newsletters and notices, and hand over the club’s filing and authority trail.',
  lessons_json=json_array(
    json('{"title":"Verify authority, rules and the club’s record calendar","body":"On taking office, confirm the appointment, current adopted rules and the authorised home for correspondence, registers, minutes and company or club records. The online V1.2 archive is a reference until you confirm registration and adoption evidence. Build a calendar for meetings, member reminders, AGM reports, required notifications and renewals. Use current Queensland Fair Trading guidance to confirm which filings and deadlines apply. Agree deputy coverage and what needs the Treasurer, Chair or Webmaster.\n\nKeep the filing calendar, adopted-rules reference, responsible officer and authorised records folder in the authorised record.","captureNotes":"Walk through #committee/handover with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/handover Include the filing calendar, adopted-rules reference, responsible officer and authorised records folder using invented details. Confirm any meeting or filing procedures against the current adopted or proposed rules as applicable and current Queensland Fair Trading guidance. For child-related duties, check the designated safeguarding lead and current Queensland guidance.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"Your shared calendar lists a filing date copied from an old term. What should you do?","choices":[{"id":"a","text":"Check current official requirements and the record that sets the date, then assign a filing owner."},{"id":"b","text":"Keep the old date unless a reminder from the regulator arrives."}],"correct_choice_id":"a","explanation":"The operating record needs the filing calendar, adopted-rules reference, responsible officer and authorised records folder. This lets the next person verify the work and any remaining decision.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/handover"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record gives the incoming person enough evidence to follow up?","choices":[{"id":"a","text":"an old officer diary with reminders but no source"},{"id":"b","text":"the filing calendar, adopted-rules reference, responsible officer and authorised records folder"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/handover"]}]}'),
    json('{"title":"Call meetings and manage notices, agendas and papers","body":"Identify the meeting type, purpose and eligibility under the current rules. Agree date, venue or approved remote arrangements and papers with the Chair. Prepare the agenda and circulate the correct notice to the correct audience, with motions and attachments where required. Record what was sent, to whom and when. Check reports, attendance and quorum preparations. Flag late nominations or proposals to the Chair for the applicable process rather than silently adding them.\n\nKeep the meeting notice, audience, send evidence, agenda version and applicable rule check in the authorised record.","captureNotes":"Walk through #committee/meetings with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/meetings Include the meeting notice, audience, send evidence, agenda version and applicable rule check using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A proposed resolution arrives after a notice has gone out. What do you check?","choices":[{"id":"a","text":"Whether there is enough room to add it to the agenda attachment."},{"id":"b","text":"Whether the notice and rules allow it at this meeting or it needs separate notice or deferral."}],"correct_choice_id":"b","explanation":"The operating record needs the meeting notice, audience, send evidence, agenda version and applicable rule check. This lets the next person verify the work and any remaining decision.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/meetings"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which evidence belongs in the work record for this step?","choices":[{"id":"a","text":"the meeting notice, audience, send evidence, agenda version and applicable rule check"},{"id":"b","text":"a revised agenda with no evidence of how members were notified"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/meetings"]}]}'),
    json('{"title":"Minute decisions, then release the right version","body":"During the meeting, record attendance, quorum, disclosures and handling, actual motions, amendments, vote outcomes and action owners. If recording is proposed, seek the required consent and agree custody and retention. Treat speech transcription and AI suggestions as working material, use the separate approval for any AI processing and verify wording against participants and the meeting record. Track draft, approved and released states separately. Publish the authorised member edition and keep originals and sensitive material private.\n\nKeep the approved minute, separate member edition, consent records and action source in the authorised record.","captureNotes":"Walk through #committee/meetings with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/meetings Include the approved minute, separate member edition, consent records and action source using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A transcript suggestion changes who is responsible for an action. What belongs in the approved minutes?","choices":[{"id":"a","text":"The allocation confirmed by the actual meeting, after checking with the chair or decision source."},{"id":"b","text":"The suggested allocation because it appears in the draft transcript."}],"correct_choice_id":"a","explanation":"The operating record needs the approved minute, separate member edition, consent records and action source. This lets the next person verify the work and any remaining decision.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/meetings"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would make this part of the handover usable?","choices":[{"id":"a","text":"a text transcript with a publish flag and no verification"},{"id":"b","text":"the approved minute, separate member edition, consent records and action source"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/meetings"]}]}'),
    json('{"title":"Run AGM preparation, elections and statutory follow-up","body":"Start with the signed prior AGM record and current rules. Confirm whether the next meeting is newly called or a continuation and what notice, nominations, quorum and voting procedures apply. Track Treasurer’s statements and reports, nominations, check-in, declared results and action owners. Keep the actual evidence of elections and approvals. Confirm relevant annual return and officer change steps with Fair Trading, keep lodgement receipts and escalate a gap without backdating records.\n\nKeep the AGM papers, eligibility and nomination checks, outcomes, filing owners and lodgement evidence in the authorised record.","captureNotes":"Walk through #committee/agm-jobs with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/agm-jobs Include the AGM papers, eligibility and nomination checks, outcomes, filing owners and lodgement evidence using invented details. Confirm any meeting or filing procedures against the current adopted or proposed rules as applicable and current Queensland Fair Trading guidance. For child-related duties, check the designated safeguarding lead and current Queensland guidance.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"Previous minutes say the AGM had no quorum and do not show whether it adjourned. How do you proceed?","choices":[{"id":"a","text":"List the next meeting as a continuation so everyone can use the original notice."},{"id":"b","text":"Check the original notice, minutes and current rules and confirm the proper next process before notifying members."}],"correct_choice_id":"b","explanation":"The operating record needs the AGM papers, eligibility and nomination checks, outcomes, filing owners and lodgement evidence. This lets the next person verify the work and any remaining decision.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/agm-jobs"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record would let an independent reviewer check the result?","choices":[{"id":"a","text":"the AGM papers, eligibility and nomination checks, outcomes, filing owners and lodgement evidence"},{"id":"b","text":"a date in the calendar with an assumed reporting status"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/agm-jobs"]}]}'),
    json('{"title":"Maintain the member register and run applications and returns","body":"Keep the current member register and original record references together. Review applications and renewals through the club’s process, check for duplicates, category and existing number, and record the actual outcome. The Treasurer confirms payment, relevant fee and waiver. Use the returns desk for authorised welcome-back offers and one-time links for the intended recipient. Track member pack, renewal messages and restricted guardian or youth review separately. Handle corrections and access requests via the authorised club process.\n\nKeep the member decision and number reference, Treasurer check, invite and pack status in the authorised record.","captureNotes":"Walk through #committee/applications with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/applications Include the member decision and number reference, Treasurer check, invite and pack status using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A returning member has two possible old numbers and a claimed payment. What is the next step?","choices":[{"id":"a","text":"Reconcile the old register, ask the Treasurer to verify payment or waiver and keep issuing on hold until confirmed."},{"id":"b","text":"Assign a new number and issue a link now, then merge the records after sign-in."}],"correct_choice_id":"a","explanation":"The operating record needs the member decision and number reference, Treasurer check, invite and pack status. This lets the next person verify the work and any remaining decision.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/applications"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would let the next person verify this work?","choices":[{"id":"a","text":"a list of names and provisional numbers without verification"},{"id":"b","text":"the member decision and number reference, Treasurer check, invite and pack status"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/applications"]}]}'),
    json('{"title":"Triage correspondence, complaints and private records","body":"At each office check-in, sort correspondence into information, a reply, a formal decision or an urgent concern. Pass finance and material commitments to the Treasurer and Chair. Route safety, youth, privacy or complaints through the designated private contact and current process. Keep the authorised record of receipt, decision, actions and deadline and protect access to supporting documents. Use committee notices and officer lists for appropriate summaries with owners and follow up what is overdue.\n\nKeep the restricted record reference, responsible recipient, deadline and approved reply status in the authorised record.","captureNotes":"Walk through #committee/notices with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/notices Include the restricted record reference, responsible recipient, deadline and approved reply status using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A grievance arrives with a private attachment and a short reply deadline. What is appropriate?","choices":[{"id":"a","text":"Put the attachment on the general committee noticeboard so all officers can respond."},{"id":"b","text":"Log receipt and deadline privately, send it to the authorised complaint contact and limit further circulation."}],"correct_choice_id":"b","explanation":"The operating record needs the restricted record reference, responsible recipient, deadline and approved reply status. This lets the next person verify the work and any remaining decision.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/notices"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record gives the incoming person enough evidence to follow up?","choices":[{"id":"a","text":"the restricted record reference, responsible recipient, deadline and approved reply status"},{"id":"b","text":"a copy of the complaint in the general action list"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/notices"]}]}'),
    json('{"title":"Coordinate releases, decisions and partner paperwork","body":"Work with the Assistant Secretary on issue ownership, contributor deadlines, member preview, monthly opt-in birthday review and controlled member delivery. Check the President’s clearance and record what was actually published. Use approved minutes for instructions about funds, events and partnerships. For a Ready SETCO task, file the approved motion, exact delegation, duties retained by PLFC, club lead, written acceptance and review or close date. Keep the source decision accessible to authorised officers.\n\nKeep the released edition or delegation scope, authority, acceptance reference and follow-up owner in the authorised record.","captureNotes":"Walk through #committee/news with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/news Include the released edition or delegation scope, authority, acceptance reference and follow-up owner using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"The partner offers to cover a task but the agreed delegation describes something else. What do you file?","choices":[{"id":"a","text":"Record the offer and open discrepancy, then refer the scope for a confirmed decision and written acceptance."},{"id":"b","text":"File the offer as acceptance of the existing motion because it came from the partner."}],"correct_choice_id":"a","explanation":"The operating record needs the released edition or delegation scope, authority, acceptance reference and follow-up owner. This lets the next person verify the work and any remaining decision.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/news"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which evidence belongs in the work record for this step?","choices":[{"id":"a","text":"the latest email or newsletter draft alone"},{"id":"b","text":"the released edition or delegation scope, authority, acceptance reference and follow-up owner"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/news"]}]}'),
    json('{"title":"Hand over retained records and pending business","body":"Prepare a dated transfer with the current rules, latest signed records, next notices, nominations or filings, private correspondence and register controls. Identify owners of outstanding actions, access, member issues and public replies. Hand over a reference to archived records and club property rather than copying private content into training. Agree who can complete the filings, confirm individual access with the Webmaster and review outstanding matters within the first week.\n\nKeep a handover register with document references, filing evidence or gaps, access and a review date in the authorised record.","captureNotes":"Walk through #committee/handover with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/handover Include a handover register with document references, filing evidence or gaps, access and a review date using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"The incoming Secretary finds a missing filing receipt. How should you close the transfer?","choices":[{"id":"a","text":"Mark it filed because the paperwork is signed and stored in the right folder."},{"id":"b","text":"Flag it as an open verification, find the responsible person and confirm the source or next contact."}],"correct_choice_id":"b","explanation":"The operating record needs a handover register with document references, filing evidence or gaps, access and a review date. This lets the next person verify the work and any remaining decision.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/handover"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would make this part of the handover usable?","choices":[{"id":"a","text":"a handover register with document references, filing evidence or gaps, access and a review date"},{"id":"b","text":"a shared login and a checklist full of assumed completions"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/handover"]}]}')
  ),
  practical='Build a fictional Secretary’s file for one committee meeting and an AGM. Include the notice and nomination register, agenda and papers, a draft and approved minute extract, action assignments, and evidence of what may be released to members. Add a member renewal or return case with payment and guardian or privacy checks, a draft newsletter clearance and a filing calendar with owners. Demonstrate from the pack what is due, what is private and how the next Secretary can verify every decision. Ask for revision if a filing date, approval, membership gate or release audience is assumed.',
  edit_version=edit_version+1
WHERE course_id='plfc-secretary' AND revision=1 AND state='draft' AND edit_version=1 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='A quick tour for anyone curious about the fishing club, its website or their first local meet.',
  lessons_json=json_array(
    json('{"title":"Start with the public clubhouse","body":"Find the fishing guide, conditions, club calendar and public events. Open the demo and choose Guide me if you want help getting around. Confirm the details of an event with the organiser before travelling.","captureNotes":"Record the demo homepage, calendar and fishing guide using public or fictional examples. Reference site: https://plfc-clubhouse.auraofintelligence.workers.dev/"}'),
    json('{"title":"Find the right door","body":"Use the join information to compare membership options. Members use their own sign-in for the areas they are allowed to see. If you are unsure which area to use, ask the club through its published contact route."}'),
    json('{"title":"Recognise public, preview and signed-in pages","body":"Use the public guide and events without an account. A preview can explain a workflow; your own account and the club’s decision determine access to private member or committee work. Ask the club which current route applies to joining, support or visiting.","captureNotes":"Walk through Clubhouse home and Help with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/"}'),
    json('{"title":"Understand events, shop and the latest status","body":"Check whether a listing is confirmed or an example and who can verify timing, participation or delivery. A product enquiry is the start of a conversation about stock, price and pickup. Wait for the club’s confirmation before treating a space or product as reserved.","captureNotes":"Walk through What’s on and Shop with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/"}'),
    json('{"title":"Find the right help for an issue","body":"Use the organiser for event details, the club contact for membership and Webmaster help for access. Use official authorities for current fishing or emergency advice. Keep account details and private records out of a public enquiry and report site errors with the page and issue.","captureNotes":"Walk through Club contact, Webmaster help and public sources with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/"}')
  ),
  practical='',
  edit_version=edit_version+1
WHERE course_id='plfc-site-tour' AND revision=1 AND state='draft' AND edit_version=1 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Find club gatherings, member notices and ways to help out socially.',
  lessons_json=json_array(
    json('{"title":"Find a gathering","body":"Use public events and member updates to find a gathering. Confirm what is open to your category with the club contact.","captureNotes":"Show a fictional social meet in the public demo calendar. Reference site: https://plfc-clubhouse.auraofintelligence.workers.dev/"}'),
    json('{"title":"Put your hand up for a task","body":"If you offer to help with a meal or fundraiser, confirm the shift with the organiser. Ask which announcements or photos can be shared."}'),
    json('{"title":"Check your category and communications","body":"Ask the club which events or member updates your category includes and what happens at renewal. Choose the contact options you want and use your own account. Check guest arrangements separately for each event before passing on invitations.","captureNotes":"Walk through Clubhouse membership information with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/"}'),
    json('{"title":"Make a workable social contribution","body":"If you offer food, equipment or time, agree the task and what the organiser needs to know about handling, venue, timing and collection. Confirm who takes the lead and who can approve any expense or media sharing. Record changes via the club contact.","captureNotes":"Walk through Events and fundraising with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/"}'),
    json('{"title":"Close the loop after a gathering","body":"Check the current announcement before travelling. If a plan changes, use the organiser’s update rather than spreading unverified details. Return borrowed items and report any issue privately to the lead. Choose which photos or names are cleared before posting.","captureNotes":"Walk through Club event information and member updates with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/"}')
  ),
  practical='',
  edit_version=edit_version+1
WHERE course_id='plfc-social-member' AND revision=1 AND state='draft' AND edit_version=1 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Run club income and payments, fees and waivers, stock and sales, assets, fundraising and grants, and prepare the year-end and handover evidence.',
  lessons_json=json_array(
    json('{"title":"Take over the accounts and payment authority","body":"Confirm the Treasurer appointment, current rules, committee financial decisions and authorised finance systems. Check bank and payment provider account holders, monetary limits, approving officers, recurring bills, insurance or other commitments and private ledger access. Save an opening balance and outstanding item list from the prior authorised record. Have changes to bank or system access processed by the provider and authorised administrator, with an independent check and no shared sign-ins.\n\nKeep the opening balances, payment authority, current commitments and role access status in the authorised record.","captureNotes":"Walk through #committee/handover with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/handover Include the opening balances, payment authority, current commitments and role access status using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A supplier asks you to use the former Treasurer’s login for a transfer. What is the proper next step?","choices":[{"id":"a","text":"Use the previous login while the bank updates the role."},{"id":"b","text":"Confirm your own authorised access and check the payment approval before acting."}],"correct_choice_id":"b","explanation":"The operating record needs the opening balances, payment authority, current commitments and role access status. This lets the next person verify the work and any remaining decision.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/handover"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record would let an independent reviewer check the result?","choices":[{"id":"a","text":"the opening balances, payment authority, current commitments and role access status"},{"id":"b","text":"a bank link and the outgoing officer’s password"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/handover"]}]}'),
    json('{"title":"Record receipts, banking and exceptions","body":"Match each cash or card receipt, Square payout and bank entry to its source, including separate fee and refund entries where the provider reports them. Record the receipt sequence or durable reference. Use agreed counting, deposit and petty cash records. Reconcile opening balance, receipts, payments and closing balance and flag duplicates, unmatched deposits and chargebacks. Preserve historical evidence and ask the relevant officer to resolve a discrepancy.\n\nKeep the receipt and statement references, reconciliation, discrepancy owner and date in the authorised record.","captureNotes":"Walk through #stock/reports with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/#stock/reports Include the receipt and statement references, reconciliation, discrepancy owner and date using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A Square payout is lower than the sum of individual sales. What do you do before reconciling it?","choices":[{"id":"a","text":"Check fees, refunds, batching and deposit evidence and leave a variance open until explained."},{"id":"b","text":"Change the sale values to match what was deposited."}],"correct_choice_id":"a","explanation":"The operating record needs the receipt and statement references, reconciliation, discrepancy owner and date. This lets the next person verify the work and any remaining decision.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#stock/reports"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would let the next person verify this work?","choices":[{"id":"a","text":"a balanced total made by adjusting individual entries without evidence"},{"id":"b","text":"the receipt and statement references, reconciliation, discrepancy owner and date"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#stock/reports"]}]}'),
    json('{"title":"Control approvals, payments and pricing","body":"Before paying, confirm the invoice or expense, budget owner, approval or ratification procedure and correct payee. Check altered account details with an established supplier contact, then record receipt, approver and payment reference. For shop, membership and event prices use the Treasurer’s price control and verify the current public price and officer alerts. Agree credits, refunds, cash limits and discretionary changes with the authorised officers and record exceptions for the committee report.\n\nKeep the invoice, independent payee check where needed, payment authority and actual transaction reference in the authorised record.","captureNotes":"Walk through #stock with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/#stock Include the invoice, independent payee check where needed, payment authority and actual transaction reference using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"An invoice shows a new bank account and requests urgent payment. What should you do?","choices":[{"id":"a","text":"Use the new account because it appears on a familiar invoice layout."},{"id":"b","text":"Verify the account change through the established supplier contact and confirm the approval before paying."}],"correct_choice_id":"b","explanation":"The operating record needs the invoice, independent payee check where needed, payment authority and actual transaction reference. This lets the next person verify the work and any remaining decision.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#stock"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record gives the incoming person enough evidence to follow up?","choices":[{"id":"a","text":"the invoice, independent payee check where needed, payment authority and actual transaction reference"},{"id":"b","text":"an invoice marked paid with no verification or decision evidence"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#stock"]}]}'),
    json('{"title":"Verify members, fees, waivers and refunds","body":"Read the current approved fees and terms for the member or event category. Match real payment to the named membership or event record and retain the receipt or refund reference. Review the proposed returning-member waiver in its authorised desk and record the amount waived separately from cash received. Tell the Secretary what cleared, what is still pending and who handles a discrepancy privately. Check any discount or birthday offer has its own approved terms and never infer that an invitation proves payment.\n\nKeep the relevant fee, payment or waiver evidence, review date and status sent to the Secretary in the authorised record.","captureNotes":"Walk through #stock/returning with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/#stock/returning Include the relevant fee, payment or waiver evidence, review date and status sent to the Secretary using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"An application shows an intended free year but no waiver decision. What does the ledger show?","choices":[{"id":"a","text":"A proposed waiver awaiting decision, separate from paid income and activation."},{"id":"b","text":"A paid membership for zero dollars and an instruction to send a link."}],"correct_choice_id":"a","explanation":"The operating record needs the relevant fee, payment or waiver evidence, review date and status sent to the Secretary. This lets the next person verify the work and any remaining decision.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#stock/returning"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which evidence belongs in the work record for this step?","choices":[{"id":"a","text":"a member name with a checked box but no decision"},{"id":"b","text":"the relevant fee, payment or waiver evidence, review date and status sent to the Secretary"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#stock/returning"]}]}'),
    json('{"title":"Run shop orders, stocktakes and supplier costs","body":"Match a shop enquiry or pickup reference to the product, stock and collection agreement. Confirm price and payment from authorised records before marking the sale complete. Use receive stock, delivery invoices and physical counts to check quantities and supplier cost evidence. Review discrepancies, returns and damaged goods. Keep the asset or stock register current, flag missing unit costs and use the documented cost basis in reports. Identify obsolete, loaned or outstanding items for follow-up.\n\nKeep the sale and collection references, physical count, unit cost source and open differences in the authorised record.","captureNotes":"Walk through #stock with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/#stock Include the sale and collection references, physical count, unit cost source and open differences using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A delivery is counted and its invoice has not arrived. What should appear?","choices":[{"id":"a","text":"The stock value as final using the previous supplier cost without a note."},{"id":"b","text":"The received quantity, missing cost status and the person checking the invoice."}],"correct_choice_id":"b","explanation":"The operating record needs the sale and collection references, physical count, unit cost source and open differences. This lets the next person verify the work and any remaining decision.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#stock"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would make this part of the handover usable?","choices":[{"id":"a","text":"the sale and collection references, physical count, unit cost source and open differences"},{"id":"b","text":"a closing estimate with no count or cost evidence"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#stock"]}]}'),
    json('{"title":"Manage fundraiser, grants, sponsors and assets","body":"Before committing funds, check the approved scope, applicant, donor or sponsor terms, restricted spending and who can vary the budget. For events confirm float, takings, deposits, costs and separate counts with the lead. Record which sponsor offers are approved and the agreed acknowledgement. For grants track evidence, eligible costs, delivery milestones, variations and acquittal dates. Keep an asset register with owner, location, custody and equipment disposal approval.\n\nKeep the conditional funding, actual transaction and asset evidence, receipts and reporting owner in the authorised record.","captureNotes":"Walk through #committee/grants with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/grants Include the conditional funding, actual transaction and asset evidence, receipts and reporting owner using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A grant-funded item may be substituted for another. What is the right next check?","choices":[{"id":"a","text":"Review the funding conditions and get the appropriate written approval before spending on the change."},{"id":"b","text":"Buy the substitute because the price fits the same total."}],"correct_choice_id":"a","explanation":"The operating record needs the conditional funding, actual transaction and asset evidence, receipts and reporting owner. This lets the next person verify the work and any remaining decision.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/grants"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record would let an independent reviewer check the result?","choices":[{"id":"a","text":"one projected income figure with no commitment or restriction details"},{"id":"b","text":"the conditional funding, actual transaction and asset evidence, receipts and reporting owner"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/grants"]}]}'),
    json('{"title":"Close reporting periods and prepare the AGM","body":"Use monthly, quarterly or year-end reports as needed. The clubhouse uses 30 June as the club financial year end. Reconcile figures against the current statements, stock and restricted funds. Separate missed evidence, waivers, receipts, outstanding obligations and archived figures. Use current Fair Trading requirements and the club rules to check the applicable reporting level, reviewer or audit, filings and due dates. Present the Treasurer’s report to the committee and provide the agreed AGM material to the Secretary. Record approval, retention and lodgement reference.\n\nKeep the reconciliation, variance list, year-end and AGM reports, approval and filing owner in the authorised record.","captureNotes":"Walk through #stock/reports with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/#stock/reports Include the reconciliation, variance list, year-end and AGM reports, approval and filing owner using invented details. Confirm any meeting or filing procedures against the current adopted or proposed rules as applicable and current Queensland Fair Trading guidance. For child-related duties, check the designated safeguarding lead and current Queensland guidance.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A stock report has missing costs when the AGM pack is due. What do you report?","choices":[{"id":"a","text":"Remove the affected lines so the valuation appears final."},{"id":"b","text":"Show and explain the unresolved valuations, reconciliation and decision or correction timeline."}],"correct_choice_id":"b","explanation":"The operating record needs the reconciliation, variance list, year-end and AGM reports, approval and filing owner. This lets the next person verify the work and any remaining decision.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#stock/reports"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would let the next person verify this work?","choices":[{"id":"a","text":"the reconciliation, variance list, year-end and AGM reports, approval and filing owner"},{"id":"b","text":"an unsigned balance summary without an evidence trail"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#stock/reports"]}]}'),
    json('{"title":"Hand over private finance work","body":"Walk the successor through reports, bank and ledger reconciliation, grants and asset register. List upcoming payments, unresolved refunds, waiver or invoice checks, report and tax or filing dates where applicable and authorised contacts. Hand over devices, physical records and cash using a custody record and verified count. Check independently that incoming access works and outgoing access has been reviewed. Give the newsletter only the approved summary for its audience. Schedule the first reconciliation review.\n\nKeep opening balances and access checks, liabilities, private source records and named follow-up in the authorised record.","captureNotes":"Walk through #committee/handover with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/handover Include opening balances and access checks, liabilities, private source records and named follow-up using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"The incoming Treasurer can see the ledger but cannot verify last month’s bank reconciliation. What should stay open?","choices":[{"id":"a","text":"The source and approver needed, a named person to resolve the gap and a check-in date."},{"id":"b","text":"The handover can be closed because the balance is on the dashboard."}],"correct_choice_id":"a","explanation":"The operating record needs opening balances and access checks, liabilities, private source records and named follow-up. This lets the next person verify the work and any remaining decision.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/handover"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record gives the incoming person enough evidence to follow up?","choices":[{"id":"a","text":"an exported report sent to a general committee list"},{"id":"b","text":"opening balances and access checks, liabilities, private source records and named follow-up"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/handover"]}]}')
  ),
  practical='Use fictional cash, Square and bank records, membership, stock and a grant. Submit a reconciliation showing one held discrepancy, a payment with authority and receipt, a fee waiver distinct from cash, a stock valuation with missing cost flagged, and a fundraiser close-out. Prepare a committee report and outline the year-end reporting checks and successor’s bank or system access. Pass when figures reconcile or variances are explained, references trace to the source, and spending authority and review are visible.',
  edit_version=edit_version+1
WHERE course_id='plfc-treasurer' AND revision=1 AND state='draft' AND edit_version=1 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Provide authorised chair cover, take responsibility for local meets and interclub coordination, and carry work across the committee, events and newsletter desks.',
  lessons_json=json_array(
    json('{"title":"Agree delegation and chair cover","body":"Read the confirmed appointment and current rules with the President and Secretary. Agree what you will lead or follow up, what is reserved for the President or committee and how somebody records cover if circumstances change. Before leading a meeting check its type, notice, quorum, conflicts and chairing procedure. If you cannot verify your authority, ask the Secretary to record the issue and arrange the next step.\n\nKeep the cover, limits, meeting basis and decisions still needing referral in the authorised record.","captureNotes":"Walk through #committee/handover with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/handover Include the cover, limits, meeting basis and decisions still needing referral using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"The President is absent and an extra motion requires authority outside the cover agreement. How do you proceed?","choices":[{"id":"a","text":"Use the verified rules and seek the appropriate decision route before acting on the extra motion."},{"id":"b","text":"Treat taking the chair as full authority to decide on the extra business."}],"correct_choice_id":"a","explanation":"The operating record needs the cover, limits, meeting basis and decisions still needing referral. This lets the next person verify the work and any remaining decision.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/handover"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would let the next person verify this work?","choices":[{"id":"a","text":"the calendar invitation and the absent officer’s title"},{"id":"b","text":"the cover, limits, meeting basis and decisions still needing referral"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/handover"]}]}'),
    json('{"title":"Maintain the action pipeline","body":"After the meeting check the motions and actions with the Chair and Secretary. Use officer lists and committee notices to take a task, record its dependency and ask for help if it is held up. Verify completion evidence and report any inconsistent record. Keep dates, venues and gear proposals off confirmed communications until the owners have checked them.\n\nKeep the decision source, owner, evidence, dependency and next check in the authorised record.","captureNotes":"Walk through #committee/todo with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/todo Include the decision source, owner, evidence, dependency and next check using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A job is marked complete on a work list but the venue approval is still pending. What goes back to the committee?","choices":[{"id":"a","text":"A complete status because the officer ticked their part of the job."},{"id":"b","text":"The completed part, open venue check, decision owner and a due date."}],"correct_choice_id":"b","explanation":"The operating record needs the decision source, owner, evidence, dependency and next check. This lets the next person verify the work and any remaining decision.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/todo"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record gives the incoming person enough evidence to follow up?","choices":[{"id":"a","text":"the decision source, owner, evidence, dependency and next check"},{"id":"b","text":"an informal assurance with no source or due date"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/todo"]}]}'),
    json('{"title":"Plan local meets and competitions","body":"Prepare a run sheet for the next local meet with purpose, date, meeting location and backup, gear lead, participant welcome, club rules, supervision and conditions checks. Check the appropriate fishing and venue information and confirm who can pause, cancel or notify the group. Agree the method of recording results or prizes before announcing them. Ask the authorised lead how juniors, grievances and incident records are to be handled.\n\nKeep the current run sheet, permission and go or pause owner plus a communication route in the authorised record.","captureNotes":"Walk through #committee/events with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/events Include the current run sheet, permission and go or pause owner plus a communication route using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"Forecasts changed and the run sheet has no cancellation contact. What is the priority?","choices":[{"id":"a","text":"Get the responsible decision and notification process confirmed before telling people to attend."},{"id":"b","text":"Use the original public start time and let each person decide how the club should respond."}],"correct_choice_id":"a","explanation":"The operating record needs the current run sheet, permission and go or pause owner plus a communication route. This lets the next person verify the work and any remaining decision.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/events"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which evidence belongs in the work record for this step?","choices":[{"id":"a","text":"a flyer with a date and no safety or decision contact"},{"id":"b","text":"the current run sheet, permission and go or pause owner plus a communication route"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/events"]}]}'),
    json('{"title":"Coordinate with clubs and outside partners","body":"Ask a neighbouring club about the possible format, dates, member or visitor arrangements and responsibilities. Record which requests are offers, confirmed commitments or still in review. If Ready SETCO is asked to help, use the approved scope, duties retained by PLFC, contacts, written acceptance and review or close date. Bring any cost and public wording to the authorised officers for approval.\n\nKeep the correspondence and status, approved scope and date of next confirmation in the authorised record.","captureNotes":"Walk through #committee/events with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/events Include the correspondence and status, approved scope and date of next confirmation using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A visiting club agrees to discuss dates and a social draft calls them a confirmed partner. What changes?","choices":[{"id":"a","text":"Keep the wording and insert a small note about outstanding scheduling."},{"id":"b","text":"Correct the status in the draft and record who can confirm dates and commitments."}],"correct_choice_id":"b","explanation":"The operating record needs the correspondence and status, approved scope and date of next confirmation. This lets the next person verify the work and any remaining decision.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/events"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would make this part of the handover usable?","choices":[{"id":"a","text":"the correspondence and status, approved scope and date of next confirmation"},{"id":"b","text":"a private screenshot interpreted as an agreement"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/events"]}]}'),
    json('{"title":"Support fundraising, gear and volunteer shifts","body":"Agree what is to be sold or collected and what approval the club needs. Allocate run sheet jobs to confirmed helpers, circulate the briefing, check borrowing and return of gear and use named contacts for restrictions and concerns. Agree float or takings handover and receipts with the Treasurer. Record equipment faults, a lost item or unfilled job promptly and take scope changes to the lead.\n\nKeep the role roster, equipment issue and return, finance handover and exceptions in the authorised record.","captureNotes":"Walk through #committee/events with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/events Include the role roster, equipment issue and return, finance handover and exceptions using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A fundraiser asks you to collect cash without an agreed handover. What should you check?","choices":[{"id":"a","text":"Who is authorised, the count and reporting method, and when the Treasurer takes custody."},{"id":"b","text":"Keep a personal record and hand over an estimate after the event."}],"correct_choice_id":"a","explanation":"The operating record needs the role roster, equipment issue and return, finance handover and exceptions. This lets the next person verify the work and any remaining decision.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/events"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record would let an independent reviewer check the result?","choices":[{"id":"a","text":"a volunteer list with no custody or cash records"},{"id":"b","text":"the role roster, equipment issue and return, finance handover and exceptions"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/events"]}]}'),
    json('{"title":"Send updates people can act on","body":"Draft your club contribution from confirmed details for a local meet, invitational, acknowledgement or volunteer request. Check the calendar and public permissions before entering it for newsletter review. Work with the Secretaries to track the status and agreed publishing channel. In Social Planner record agreed timing, review and the actual public link. If an event changes have the lead approve updated wording and send it through the agreed channels.\n\nKeep the current wording, source, approved channels and correction check in the authorised record.","captureNotes":"Walk through #committee/news with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/news Include the current wording, source, approved channels and correction check using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A published post has the old meeting point. What should happen?","choices":[{"id":"a","text":"Put the new information in committee notes and wait for people to ask."},{"id":"b","text":"Confirm the correction with the lead, update the approved channels and verify what visitors can see."}],"correct_choice_id":"b","explanation":"The operating record needs the current wording, source, approved channels and correction check. This lets the next person verify the work and any remaining decision.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/news"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would let the next person verify this work?","choices":[{"id":"a","text":"the current wording, source, approved channels and correction check"},{"id":"b","text":"the old link plus a comment that the date might change"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/news"]}]}'),
    json('{"title":"Hand over deputy and event responsibilities","body":"Walk the next Vice President through coverage limits, agenda and decisions, active calendar, approaching events, outstanding gear or supplier issues and people the club is in discussion with. Show the duty roster and unresolved permissions or risks. Hand back any property and have access checked by the Webmaster. Confirm the shortlist of open decisions with the President and set the first-week check.\n\nKeep the event and authority register, gear and commitments, named owner and dated next review in the authorised record.","captureNotes":"Walk through #committee/handover with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/handover Include the event and authority register, gear and commitments, named owner and dated next review using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A draft agreement expires between officers. What do you pass on?","choices":[{"id":"a","text":"The exact status, responsible officer, decision needed and last date for review."},{"id":"b","text":"The partner’s details with a suggestion to contact them sometime."}],"correct_choice_id":"a","explanation":"The operating record needs the event and authority register, gear and commitments, named owner and dated next review. This lets the next person verify the work and any remaining decision.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/handover"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record gives the incoming person enough evidence to follow up?","choices":[{"id":"a","text":"the next meet title and a list of interested people"},{"id":"b","text":"the event and authority register, gear and commitments, named owner and dated next review"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/handover"]}]}')
  ),
  practical='Prepare a fictional deputy’s handover for a meeting and an interclub meet. Give the scope of chair cover, one motion and quorum or interest issue, venue and gear checks, volunteer and safety leads, partner status, costs awaiting authorisation and a reviewed club update. Show how you would respond to a weather change and leave three open actions with owners. Pass when the authority, event readiness and handover evidence can each be verified.',
  edit_version=edit_version+1
WHERE course_id='plfc-vice-president' AND revision=1 AND state='draft' AND edit_version=1 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Help a new volunteer prepare for a confirmed club task, find support and hand the work back.',
  lessons_json=json_array(
    json('{"title":"Agree on the shift","body":"Check the event run sheet with the shift lead. Confirm when and where you start, what the job involves, what equipment you need and what to do if you can''t attend. Raise access needs or questions about agreed expenses with the club contact before the event."}'),
    json('{"title":"Briefing and safeguards","body":"At check-in, ask the lead about the site, conditions, equipment and reporting arrangements. Confirm who calls a weather pause and who handles incidents or concerns. Check with the designated lead before supervising juniors, changing duties or taking photos. Follow the event''s directions if conditions or responsibilities change."}'),
    json('{"title":"Finish and hand over","body":"Return equipment and tell the shift lead about missing items, issues and unfinished tasks. If another volunteer takes over, tell them what''s done and what needs their attention. Pass private information only to the person authorised to receive it."}'),
    json('{"title":"Agree duties, checks and support","body":"Find the shift lead and the run sheet version. Confirm duties, timing, check-in, breaks, equipment, training, expenses and any required screening or supervision before agreeing. If asked to change tasks, use the person responsible for the shift, particularly for gear, juniors or cash.","captureNotes":"Walk through Events and fundraising with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/"}'),
    json('{"title":"Respond to changes and check out","body":"Ask who can change or pause an event and how you will hear confirmed instructions. Route any injury, welfare, safeguarding or privacy issue to the responsible person and agree what may be written in a shared log. If urgent, follow the event’s approved emergency process.","captureNotes":"Walk through Event run sheet and private reporting route with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/"}'),
    json('{"title":"Return custody and review what happened","body":"Count and hand back borrowed items with the lead. With any cash or collections, follow the authorised handover and count already agreed. Pass the next person the task status, what remains and who owns it. Check who can confirm any voluntary contribution record and keep feedback or sensitive matters within the right audience.","captureNotes":"Walk through Event close-out and equipment handover with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/"}')
  ),
  practical='',
  edit_version=edit_version+1
WHERE course_id='plfc-volunteer-onboarding' AND revision=1 AND state='draft' AND edit_version=2 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Maintain the clubhouse, implement documented access decisions, operate support and controlled publishing, and rehearse recovery, privacy and service handover.',
  lessons_json=json_array(
    json('{"title":"Establish authority and service ownership","body":"Confirm the Webmaster’s appointed scope and responsible club contacts. Make an inventory of the clubhouse, existing domain or publishing services, repository, database, payment links, provider accounts and backups with their owners. Distinguish the club’s existing public website from the separate clubhouse deployment and record any approved connection work. Document what the lower-risk test environment can show and who may make changes.\n\nKeep the service and asset inventory, exact scope, authority and approved contacts in the authorised record.","captureNotes":"Walk through #committee/handover with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/handover Include the service and asset inventory, exact scope, authority and approved contacts using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A club officer asks to point the legacy public domain at the clubhouse. What do you check?","choices":[{"id":"a","text":"The approved decision, domain owner, scope and rollback before scheduling any change."},{"id":"b","text":"Change it as soon as the clubhouse is reachable because it serves the same club."}],"correct_choice_id":"a","explanation":"The operating record needs the service and asset inventory, exact scope, authority and approved contacts. This lets the next person verify the work and any remaining decision.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/handover"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which evidence belongs in the work record for this step?","choices":[{"id":"a","text":"a list of login addresses with no owner or decision"},{"id":"b","text":"the service and asset inventory, exact scope, authority and approved contacts"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/handover"]}]}'),
    json('{"title":"Invite, change and revoke individual access","body":"Check role instructions against the club’s approved decision and source member or office record. Confirm identity and the intended private recipient. Use individual accounts, time-limited invitations and the least access required. Record expiry and outcome and review stale invitations, lost credentials and outgoing roles. Verify that added roles work and revoked permissions are denied from a separate session. Leave membership, money and safeguarding approvals with their authorised officers.\n\nKeep the access decision, assigned scope, expiry, verification and revocation status in the authorised record.","captureNotes":"Walk through #committee/handover with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/handover Include the access decision, assigned scope, expiry, verification and revocation status using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"Someone requests the former office account so they can pick up work. What do you do?","choices":[{"id":"a","text":"Give the former account briefly and reset it once the transition is complete."},{"id":"b","text":"Confirm the current appointment and issue or update their own scoped account."}],"correct_choice_id":"b","explanation":"The operating record needs the access decision, assigned scope, expiry, verification and revocation status. This lets the next person verify the work and any remaining decision.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/handover"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would make this part of the handover usable?","choices":[{"id":"a","text":"the access decision, assigned scope, expiry, verification and revocation status"},{"id":"b","text":"a shared login or a role label copied into the general register"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/handover"]}]}'),
    json('{"title":"Support member and officer access privately","body":"Use the help route and agreed club contacts to identify the affected service and account with minimum information. Check whether an issue is sign-in, membership payment, guardian approval or missing scope and route each to the correct owner. Never ask for a password or a live activation link through help. Use a safe test account when reproducing and record results, responses and time to follow up.\n\nKeep the minimum ticket reference, issue class, authorised owner and actual resolution in the authorised record.","captureNotes":"Walk through /webmaster-help.html with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/webmaster-help.html Include the minimum ticket reference, issue class, authorised owner and actual resolution using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A junior account cannot use social functions. What do you do?","choices":[{"id":"a","text":"Refer the separate guardian and club review to the responsible team and keep the access request private."},{"id":"b","text":"Enable the feature because the account already signed in successfully."}],"correct_choice_id":"a","explanation":"The operating record needs the minimum ticket reference, issue class, authorised owner and actual resolution. This lets the next person verify the work and any remaining decision.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/webmaster-help.html"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record would let an independent reviewer check the result?","choices":[{"id":"a","text":"a full member export attached to a help message"},{"id":"b","text":"the minimum ticket reference, issue class, authorised owner and actual resolution"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/webmaster-help.html"]}]}'),
    json('{"title":"Maintain releases, public information and permissions","body":"Receive approved wording or instructions from the right officer, identify source and audience, check image and data permissions, and review the venue, date and accessibility details. Stage changes and test relevant public and private controls before release. Verify the result on phone and desktop, including navigation, download and sign-in where relevant. Record the deployment, public link and how to recover a bad update. Keep test and draft records out of the public build.\n\nKeep the approved change, release and audience evidence, smoke checks and rollback status in the authorised record.","captureNotes":"Walk through #committee/social with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/social Include the approved change, release and audience evidence, smoke checks and rollback status using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"An approved member newsletter was mistakenly uploaded to a public page. What should you do first?","choices":[{"id":"a","text":"Leave it up until a replacement edition has been approved."},{"id":"b","text":"Contain the exposure under the club’s incident procedure, notify the responsible officer and verify removal."}],"correct_choice_id":"b","explanation":"The operating record needs the approved change, release and audience evidence, smoke checks and rollback status. This lets the next person verify the work and any remaining decision.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/social"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would let the next person verify this work?","choices":[{"id":"a","text":"the approved change, release and audience evidence, smoke checks and rollback status"},{"id":"b","text":"a message saying the content was posted with no destination or approval"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/social"]}]}'),
    json('{"title":"Maintain integrations, secrets and payment boundaries","body":"Check the approved sender, authorisation and permissions before connecting a mail or other service. Keep deployment and runtime credentials in the private provider controls. Confirm who owns email delivery, reports, payment provider setup, licences and operational cost. Test with fictional data and record failures, delivery status and review dates. Treat published price or payment changes as Treasurer decisions with their record available to authorised people.\n\nKeep the approved provider, role owner, test results, credentials custodian and open changes in the authorised record.","captureNotes":"Walk through /club-email-setup.html with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/club-email-setup.html Include the approved provider, role owner, test results, credentials custodian and open changes using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"An email item is queued but the sender is unverified. What can the Webmaster say?","choices":[{"id":"a","text":"Delivery is pending verification and any send still needs the authorised setup and review."},{"id":"b","text":"The notice is delivered because it has a queued timestamp."}],"correct_choice_id":"a","explanation":"The operating record needs the approved provider, role owner, test results, credentials custodian and open changes. This lets the next person verify the work and any remaining decision.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/club-email-setup.html"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record gives the incoming person enough evidence to follow up?","choices":[{"id":"a","text":"an email queue screenshot marked sent with no confirmation"},{"id":"b","text":"the approved provider, role owner, test results, credentials custodian and open changes"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/club-email-setup.html"]}]}'),
    json('{"title":"Protect records and rehearse recovery","body":"Agree backup scope, schedule, custodian and restorable formats with the club. Verify recovery in an approved test environment and record what was restored, checks made and gaps. For serious outages, suspicious access or incorrect sharing, contain the affected path, preserve limited evidence, notify responsible club officers and check required reporting through the authorised process. Document the timeline and confirm restored service and denied access where needed.\n\nKeep the recovery test or incident timeline, verification and remaining responsibility in the authorised record.","captureNotes":"Walk through #committee/handover with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/handover Include the recovery test or incident timeline, verification and remaining responsibility using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A faulty deploy is rolled back and the server responds again. What else should be checked?","choices":[{"id":"a","text":"Mark fixed as soon as the homepage loads."},{"id":"b","text":"Verify the affected workflow, private permissions and record consistency before closing the issue."}],"correct_choice_id":"b","explanation":"The operating record needs the recovery test or incident timeline, verification and remaining responsibility. This lets the next person verify the work and any remaining decision.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/handover"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which evidence belongs in the work record for this step?","choices":[{"id":"a","text":"the recovery test or incident timeline, verification and remaining responsibility"},{"id":"b","text":"a screenshot of a working homepage with no workflow checks"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/handover"]}]}'),
    json('{"title":"Hand over accounts and unfinished work securely","body":"Transfer the service map, recent deploy references, backup and restore evidence, open support issues, renewals, availability and authorised administrators. Arrange provider role changes through individual accounts. Hand over equipment and recovery custody using the approved process and confirm the next contact for urgent issues. Check outgoing access, confirm the incoming officer can run an authorised release and set a review date.\n\nKeep dated transfer references, recovery locations, role checks, unfinished work and successor review in the authorised record.","captureNotes":"Walk through #committee/handover with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/handover Include dated transfer references, recovery locations, role checks, unfinished work and successor review using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"The incoming Webmaster has repo access but cannot reach the cloud deployment or recovery settings. What should you do?","choices":[{"id":"a","text":"Record the scope gap, get the approved access decision and test both responsibilities after changes."},{"id":"b","text":"Use a personal administrator''s account for provider updates until the next term."}],"correct_choice_id":"a","explanation":"The operating record needs dated transfer references, recovery locations, role checks, unfinished work and successor review. This lets the next person verify the work and any remaining decision.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/handover"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would make this part of the handover usable?","choices":[{"id":"a","text":"a code repository link and a private password copied into the pack"},{"id":"b","text":"dated transfer references, recovery locations, role checks, unfinished work and successor review"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/#committee/handover"]}]}')
  ),
  practical='Prepare a fictional Webmaster release and access handover. Test separate participant, officer and signed-out views, carry out a fictional approved invitation and revocation, show a safe public edit and rollback plan, and write a support or privacy incident record with restricted references. Also submit a recovery test and operational handover listing assets, custodians and unresolved risks. Pass when access matches documented authority, no private data is exposed, and a successor can reproduce the checks and recover the service.',
  edit_version=edit_version+1
WHERE course_id='plfc-webmaster' AND revision=1 AND state='draft' AND edit_version=1 AND edited_by IS NULL;
